 38	    public CheckoutSummary calculateSummary(CheckoutSummaryRequest request) {
 39	        validateRequest(request);
 40	
 41	        List<Product> products = getAndValidateProducts(request.getItems());
 42	        validateCoupon(request.getCoupon(), request.getItems(), products);
 43	
 44	        BigDecimal productsSubtotal = calculateProductsSubtotal(request.getItems(), products);
 45	        BigDecimal couponDiscount = calculateCouponDiscount(request.getCoupon(), request.getItems(),
 46	                products, productsSubtotal, request.getCustomer().getCpf());
 47	
 48	        BigDecimal shippingCost = BigDecimal.ZERO;
 49	        Integer deliveryDays = 0;
 50	        if (request.getShippingMethod() != ShippingMethod.STORE_PICKUP &&
 51	            request.getClubTier() != ClubTier.GOLD) {
 52	            ShippingInfo shippingInfo = calculateShipping(request.getShippingMethod(),
 53	                    request.getZipCode(), request.getItems(), products, request.getRegion());
 54	            shippingCost = shippingInfo.cost;
 55	            deliveryDays = shippingInfo.days;
 56	        } else if (request.getShippingMethod() != ShippingMethod.STORE_PICKUP &&
 57	                   request.getClubTier() == ClubTier.GOLD) {
 58	            ShippingInfo shippingInfo = calculateShipping(request.getShippingMethod(),
 59	                    request.getZipCode(), request.getItems(), products, request.getRegion());
 60	            deliveryDays = shippingInfo.days;
 61	        } else if (request.getShippingMethod() == ShippingMethod.STORE_PICKUP) {
 62	            deliveryDays = STORE_PICKUP_DAYS;
 63	        }
 64	
 65	        BigDecimal insurance = calculateInsurance(productsSubtotal, request.getRegion());
 66	
 67	        BigDecimal subtotalBeforePayment = CurrencyUtils.add(productsSubtotal,
 68	                CurrencyUtils.subtract(BigDecimal.ZERO, couponDiscount), shippingCost, insurance);
 69	
 70	        BigDecimal paymentAdjustment = calculatePaymentAdjustment(subtotalBeforePayment,
 71	                request.getPaymentMethod(), request.getInstallments());
 72	
 73	        BigDecimal finalTotal = CurrencyUtils.add(subtotalBeforePayment, paymentAdjustment);
 74	
 75	        Integer installments = request.getInstallments() != null ? request.getInstallments() : 1;
 76	        BigDecimal installmentAmount = calculateInstallmentAmount(finalTotal, installments);
 77	
 78	        BigDecimal nextPurchaseCredit = calculateNextPurchaseCredit(request.getClubTier(), productsSubtotal);
 79	
 80	        Boolean gift = request.getClubTier() == ClubTier.GOLD &&
 81	                      productsSubtotal.compareTo(new BigDecimal("500.00")) > 0;
 82	
 83	        return CheckoutSummary.builder()
 84	                .productsSubtotal(productsSubtotal)
 85	                .couponDiscount(couponDiscount)
 86	                .shippingCost(shippingCost)
 87	                .deliveryDays(deliveryDays)
 88	                .insurance(insurance)
 89	                .paymentAdjustment(paymentAdjustment)
 90	                .finalTotal(finalTotal)
 91	                .installments(installments)
 92	                .installmentAmount(installmentAmount)
 93	                .nextPurchaseCredit(nextPurchaseCredit)
 94	                .gift(gift)
 95	                .build();
 96	    }
