452	    @Transactional
453	    public OrderResponse processPayment(String orderId, PaymentNotificationRequest paymentRequest) {
454	        Optional<Order> orderOpt = orderRepository.findById(orderId);
455	
456	        if (orderOpt.isEmpty()) {
457	            throw new OrderServiceException("ORDER_NOT_FOUND", "Order not found", HttpStatus.NOT_FOUND);
458	        }
459	
460	        Order order = orderOpt.get();
461	
462	        if (order.getStatus() != OrderStatus.AWAITING_PAYMENT) {
463	            if (order.getTransactionId() != null &&
464	                order.getTransactionId().equals(paymentRequest.getTransactionId())) {
465	                return mapOrderToResponse(order);
466	            }
467	            throw new OrderServiceException("OPERATION_NOT_ALLOWED", "Order is not awaiting payment", HttpStatus.CONFLICT);
468	        }
469	
470	        if (paymentRequest.getTransactionId() == null || paymentRequest.getTransactionId().isEmpty() ||
471	            paymentRequest.getPaidAt() == null) {
472	            throw new OrderServiceException("INVALID_ORDER", "Missing transactionId or paidAt", HttpStatus.UNPROCESSABLE_ENTITY);
473	        }
474	
475	        Instant paymentTime = paymentRequest.getPaidAt();
476	        Instant orderTime = order.getCreatedAt();
477	        long hoursDiff = (paymentTime.getEpochSecond() - orderTime.getEpochSecond()) / 3600;
478	
479	        if (hoursDiff > PAYMENT_TIMEOUT_HOURS) {
480	            order.setStatus(OrderStatus.CANCELLED);
481	            orderRepository.save(order);
482	            throw new OrderServiceException("ORDER_EXPIRED", "Payment timeout", HttpStatus.CONFLICT);
483	        }
484	
485	        CheckoutSummary summary = deserializeSummary(order.getSummaryJson());
486	        List<Map<String, Object>> items;
487	        try {
488	            @SuppressWarnings("unchecked")
489	            List<Map<String, Object>> itemsList = objectMapper.readValue(order.getItemsJson(), List.class);
490	            items = itemsList;
491	        } catch (JsonProcessingException e) {
492	            throw new RuntimeException("Failed to deserialize items", e);
493	        }
494	
495	        List<Product> products = getProductsForOrder(items);
496	
497	        for (int i = 0; i < items.size(); i++) {
498	            @SuppressWarnings("unchecked")
499	            Map<String, Object> item = items.get(i);
500	            String sku = (String) item.get("sku");
501	            Long quantity = ((Number) item.get("quantity")).longValue();
502	
503	            Optional<Product> productOpt = productRepository.findById(sku);
504	            if (productOpt.isEmpty() || productOpt.get().getStock() < quantity) {
505	                order.setStatus(OrderStatus.CANCELLED);
506	                orderRepository.save(order);
507	                createNotification(order.getCustomerCpf(), NotificationType.ORDER_CANCELLED, orderId);
508	                throw new OrderServiceException("INSUFFICIENT_STOCK", "Insufficient stock", HttpStatus.CONFLICT);
509	            }
510	        }
511	
512	        order.setStatus(OrderStatus.PAID);
513	        order.setPaidAt(paymentTime);
514	        order.setTransactionId(paymentRequest.getTransactionId());
515	        order = orderRepository.save(order);
516	
517	        for (int i = 0; i < items.size(); i++) {
518	            @SuppressWarnings("unchecked")
519	            Map<String, Object> item = items.get(i);
520	            String sku = (String) item.get("sku");
521	            Long quantity = ((Number) item.get("quantity")).longValue();
522	
523	            Product product = products.get(i);
524	            product.setStock(product.getStock() - quantity);
525	            productRepository.save(product);
526	        }
527	
528	        String cpf = order.getCustomerCpf();
529	        Optional<Customer> customerOpt = customerRepository.findById(cpf);
530	        Customer customer;
531	        if (customerOpt.isEmpty()) {
532	            customer = Customer.builder()
533	                    .cpf(cpf)
534	                    .creditBalance(summary.getNextPurchaseCredit())
535	                    .build();
536	        } else {
537	            customer = customerOpt.get();
538	            customer.setCreditBalance(CurrencyUtils.add(customer.getCreditBalance(),
539	                    summary.getNextPurchaseCredit()));
540	        }
541	        customerRepository.save(customer);
542	
543	        createNotification(cpf, NotificationType.PAYMENT_APPROVED, orderId);
544	
545	        return mapOrderToResponse(order);
546	    }
