 93	    }
 94	
 95	    public static BigDecimal divide(BigDecimal a, BigDecimal b) {
 96	        return roundToCents(a.divide(b, 10, ROUNDING_MODE));
 97	    }
 98	
 99	    public static BigDecimal add(BigDecimal... values) {
100	        BigDecimal result = BigDecimal.ZERO;
101	        for (BigDecimal value : values) {
102	            if (value != null) {
103	                result = result.add(value);
104	            }
105	        }
106	        return roundToCents(result);
107	    }
108	
109	    public static BigDecimal subtract(BigDecimal a, BigDecimal b) {
110	        return roundToCents(a.subtract(b));
111	    }
112	}
